import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './catalogo.css';
import './catalogoResponsive.css';

const productos = [
  {
    id: 1,
    nombre: 'Collar de Plata Artesanal',
    categoria: 'Joyería',
    precio: 45000,
    artesano: 'María González',
  },
  {
    id: 2,
    nombre: 'Vasija de Barro Tradicional',
    categoria: 'Cerámica',
    precio: 32000,
    artesano: 'Carlos Mendoza',
  },
  {
    id: 3,
    nombre: 'Ruana de Lana Pura',
    categoria: 'Textiles',
    precio: 85000,
    artesano: 'Ana Rodríguez',
  },
  {
    id: 4,
    nombre: 'Bolso de Cuero Grabado',
    categoria: 'Cuero',
    precio: 60000,
    artesano: 'Lucía Martínez',
  },
  {
    id: 5,
    nombre: 'Escultura en Madera Tallada',
    categoria: 'Madera',
    precio: 98000,
    artesano: 'Pedro Rojas',
  },
  {
    id: 6,
    nombre: 'Lámpara de Vidrio Soplado',
    categoria: 'Vidrio',
    precio: 72000,
    artesano: 'Juliana Vega',
  },
  {
    id: 7,
    nombre: 'Billetera de Papel Reciclado',
    categoria: 'Papel',
    precio: 18000,
    artesano: 'Samuel Torres',
  },
  {
    id: 8,
    nombre: 'Pulsera de Piedra Natural',
    categoria: 'Piedra',
    precio: 25000,
    artesano: 'Andrea Gómez',
  },
  {
    id: 9,
    nombre: 'Llavero Artesanal',
    categoria: 'Otros',
    precio: 12000,
    artesano: 'Juan Pérez',
  },
];

const CatalogoProductos = () => {
  const [mostrarFiltros, setMostrarFiltros] = useState(false);

  return (
    <div className="catalogo-container">
      <button
        className="btn-filtrar-toggle"
        onClick={() => setMostrarFiltros(!mostrarFiltros)}
      >
        {mostrarFiltros ? 'Ocultar Filtros' : 'Mostrar Filtros'}
      </button>

      <aside className={`catalogo-sidebar ${mostrarFiltros ? 'visible' : 'oculto'}`}>
        <h2 className="catalogo-sidebar-title">Filtros</h2>

        <div className="catalogo-filtro-bloque">
          <h3>Categoría</h3>
          {['Joyería', 'Cerámica', 'Textiles', 'Madera', 'Cuero', 'Metal', 'Vidrio', 'Papel', 'Piedra', 'Otros'].map((cat, idx) => (
            <label key={idx} className="catalogo-filtro-opcion">
              <input type="checkbox" /> {cat}
            </label>
          ))}
        </div>

        <div className="catalogo-filtro-bloque">
          <h3>Rango de Precio</h3>
          <label className="catalogo-filtro-opcion"><input type="checkbox" /> Menos de $30.000</label>
          <label className="catalogo-filtro-opcion"><input type="checkbox" /> $30.000 - $50.000</label>
          <label className="catalogo-filtro-opcion"><input type="checkbox" /> $50.000 - $80.000</label>
          <label className="catalogo-filtro-opcion"><input type="checkbox" /> Más de $80.000</label>
        </div>

        <button className="btn-filtrar">Aplicar Filtros</button>
      </aside>

      <main className="catalogo-main">
        <h1 className="catalogo-header">Catálogo de Productos ({productos.length} productos)</h1>

        <div className="catalogo-productos-grid">
          {productos.map(producto => (
            <div key={producto.id} className="catalogo-producto-card">
              <div className="catalogo-producto-imagen" />
              <div className="catalogo-producto-info">
                <span className="catalogo-producto-categoria">{producto.categoria}</span>
                <h3 className="catalogo-producto-nombre">{producto.nombre}</h3>
                <p className="catalogo-producto-artesano">Por: {producto.artesano}</p>
                <p className="catalogo-producto-precio">${producto.precio.toLocaleString()}</p>
                <button className="btn-vermas">Ver Más</button>
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
};

export default CatalogoProductos;
